    expect(call.headers.get('Content-Type')).toBe('application/json')
    expect(call.json).toEqual({
      title: 'Success after 2 retries',
      text: 'Mailchimp API call returned HTTP 429. Retried 2 times. Final outcome: Success after 2 retries.',
      tags: ['mailchimp-retry'],
      alert_type: 'info',
    })
    expect(result.datadogEvent.status).toBe('ok')
  })

  it('includes the DD-API-KEY header for authentication', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.datadoghq.com/api/v1/events' ? jsonResponse({ status: 'ok' }, 200) : jsonResponse({}, 404)
    )

    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_after_header: '30',
      retry_count: 1,
      final_outcome: 'Failed after 1 retry',
    }

    const config: ConnectorConfig = {
      DATADOG_API_KEY: 'secret-key-123',
      fetch,
    }

    await handle(payload, config)

    expect(calls[0].headers.get('DD-API-KEY')).toBe('secret-key-123')
  })

  it('throws descriptive error when response_status is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload = {
      retry_after_header: '60',
      retry_count: 2,
      final_outcome: 'Success',
    } as unknown as MailchimpRetryPayload

    const config: ConnectorConfig = { DATADOG_API_KEY: 'key', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: response_status')
  })

  it('throws descriptive error when retry_after_header is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload = {
      response_status: 429,
      retry_count: 2,
      final_outcome: 'Success',
    } as unknown as MailchimpRetryPayload

    const config: ConnectorConfig = { DATADOG_API_KEY: 'key', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: retry_after_header')
  })

  it('throws descriptive error when retry_count is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload = {
      response_status: 429,
      retry_after_header: '60',
      final_outcome: 'Success',
    } as unknown as MailchimpRetryPayload

    const config: ConnectorConfig = { DATADOG_API_KEY: 'key', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: retry_count')
  })

