    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload = {
      response_status: 429,
      retry_after_header: '60',
      retry_count: 2,
    } as unknown as MailchimpRetryPayload

    const config: ConnectorConfig = { DATADOG_API_KEY: 'key', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: final_outcome')
  })

  it('throws error with status code and endpoint on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.datadoghq.com/api/v1/events' ? jsonResponse({ error: 'Unauthorized' }, 401) : jsonResponse({}, 404)
    )

    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_after_header: '60',
      retry_count: 2,
      final_outcome: 'Success after 2 retries',
    }

    const config: ConnectorConfig = {
      DATADOG_API_KEY: 'invalid-key',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Datadog Events API request failed: 401 Unauthorized for POST https://api.datadoghq.com/api/v1/events'
    )
    expect(calls).toHaveLength(1)
  })

