export interface ConnectorConfig {
  /** Datadog API key for authentication (DD-API-KEY header). */
  DATADOG_API_KEY: string
  /** Optional fetch implementation for testing or customization. */
  fetch?: typeof fetch
}

export interface MailchimpRetryPayload {
  /** The HTTP status code from the Mailchimp API response (e.g., 429). */
  response_status: number
  /** The value of the Retry-After header sent by Mailchimp, as a string. */
  retry_after_header: string
  /** The number of retry attempts made (0 to 3). */
  retry_count: number
  /** Summary string describing success or final failure after retries. */
  final_outcome: string
}

export interface DatadogEventResult {
  /** The status returned by the Datadog Events API (typically "ok"). */
  status: string
}

export interface HandleResult {
  /** The Datadog event creation result. */
  datadogEvent: DatadogEventResult
}

/**
 * Handles a Mailchimp HTTP 429 retry outcome by creating a Datadog event.
 *
 * @param payload - The source payload containing retry information.
 * @param config - Connector configuration including Datadog API key.
 * @returns The Datadog event creation result.
 * @throws Error if required fields are missing or the Datadog API returns a non-2xx response.
 */
export async function handle(
  payload: MailchimpRetryPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (payload.response_status === undefined || payload.response_status === null) {
    throw new Error('Missing required field: response_status')
  }
  if (payload.retry_after_header === undefined || payload.retry_after_header === null) {
    throw new Error('Missing required field: retry_after_header')
  }
  if (payload.retry_count === undefined || payload.retry_count === null) {
    throw new Error('Missing required field: retry_count')
  }
  if (payload.final_outcome === undefined || payload.final_outcome === null) {
    throw new Error('Missing required field: final_outcome')
  }

  // Map fields to Datadog event format
  const eventBody = {
    title: payload.final_outcome,
    text: `Mailchimp API call returned HTTP ${payload.response_status}. Retried ${payload.retry_count} times. Final outcome: ${payload.final_outcome}.`,
    tags: ['mailchimp-retry'],
    alert_type: 'info' as const,
  }

  const url = 'https://api.datadoghq.com/api/v1/events'
  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'DD-API-KEY': config.DATADOG_API_KEY,
    },
    body: JSON.stringify(eventBody),
  })

  if (!response.ok) {
    throw new Error(`Datadog Events API request failed: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = (await response.json()) as DatadogEventResult
  return { datadogEvent: result }
}

